SELECT * FROM t_spd_batch
WHERE del_flag = #{delFlag}

    AND batch_no LIKE CONCAT('%', #{query.batchNo}, '%')


    AND material_id = #{query.materialId}


    AND material_name LIKE CONCAT('%', #{query.materialName}, '%')


    AND supplier_name LIKE CONCAT('%', #{query.supplierName}, '%')


    AND expiry_date >= #{query.expiryDateStart}


    AND expiry_date <= #{query.expiryDateEnd}


    AND batch_status = #{query.batchStatus}

ORDER BY create_time DESC

SELECT * FROM t_spd_batch
WHERE batch_no = #{batchNo}
AND material_id = #{materialId}
AND del_flag = #{delFlag}

    AND id != #{id}

LIMIT 1

SELECT * FROM t_spd_batch
WHERE batch_id = #{batchId}
AND del_flag = #{delFlag}
LIMIT 1
